Key config:
`connectionTimeoutMillis` → wait limit for new conn.  
`idleTimeoutMillis` → unused conn cleanup.  
`query_timeout` / `statement_timeout` → runaway query cap.  
`pool.on("error")` → idle client failures.  
`try/catch` around queries → req-level handling.

Use `pg`’s built-in `Pool`.

```bash
npm install pg
```

```js
// db.js
const { Pool } = require("pg");

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: 10,                    // max open clients
  min: 0,                     // usually keep 0 unless you need warm conns

  // Timeouts
  connectionTimeoutMillis: 5_000, // fail if new conn takes >5s
  idleTimeoutMillis: 30_000,      // close idle clients after 30s
  query_timeout: 15_000,          // server/query execution timeout
  statement_timeout: 15_000,      // PostgreSQL statement timeout
  idle_in_transaction_session_timeout: 30_000,

  // Usually true in hosted DBs requiring TLS
  ssl:
    process.env.NODE_ENV === "production"
      ? { rejectUnauthorized: true }
      : false,
});

// Required: handles errors on idle clients.
// Without this, idle connection errors can crash the process.
pool.on("error", (err) => {
  console.error("Unexpected PostgreSQL pool error", err);
});

async function query(text, params) {
  const start = Date.now();

  try {
    const result = await pool.query(text, params);
    return result;
  } catch (err) {
    console.error("PostgreSQL query failed", {
      message: err.message,
      code: err.code,
      query: text,
      durationMs: Date.now() - start,
    });

    throw err;
  }
}

async function withTransaction(fn) {
  const client = await pool.connect();

  try {
    await client.query("BEGIN");

    const result = await fn(client);

    await client.query("COMMIT");
    return result;
  } catch (err) {
    try {
      await client.query("ROLLBACK");
    } catch (rollbackErr) {
      console.error("PostgreSQL rollback failed", rollbackErr);
    }

    throw err;
  } finally {
    client.release();
  }
}

async function closePool() {
  await pool.end();
}

module.exports = {
  pool,
  query,
  withTransaction,
  closePool,
};
```

