Below is a practical React error boundary implementation using a class component, because React error boundaries still require class components for `componentDidCatch` / `getDerivedStateFromError`.

```jsx
import React from "react";

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
      retryKey: 0,
    };
  }

  static getDerivedStateFromError(error) {
    return {
      hasError: true,
      error,
    };
  }

  componentDidCatch(error, errorInfo) {
    this.setState({ errorInfo });

    // Replace this with Sentry, Datadog, LogRocket, etc.
    console.error("ErrorBoundary caught an error:", error);
    console.error("Component stack:", errorInfo.componentStack);

    if (this.props.onError) {
      this.props.onError(error, errorInfo);
    }
  }

  handleRetry = () => {
    this.setState((state) => ({
      hasError: false,
      error: null,
      errorInfo: null,
      retryKey: state.retryKey + 1,
    }));
  };

  render() {
    if (this.state.hasError) {
      if (this.props.fallback) {
        return this.props.fallback({
          error: this.state.error,
          errorInfo: this.state.errorInfo,
          retry: this.handleRetry,
        });
      }

      return (
        <div role="alert" style={styles.container}>
          <h2 style={styles.title}>Something went wrong</h2>

          <p style={styles.message}>
            The page could not render correctly. You can try again.
          </p>

          {process.env.NODE_ENV !== "production" && this.state.error && (
            <pre style={styles.details}>
              {this.state.error.toString()}
              {this.state.errorInfo?.componentStack}
            </pre>
          )}

          <button type="button" onClick={this.handleRetry} style={styles.button}>
            Retry
          </button>
        </div>
      );
    }

    return (
      <React.Fragment key={this.state.retryKey}>
        {this.props.children}
      </React.Fragment>
    );
  }
}

const styles = {
